{
  "items": [
    {
      "title": "Historical Land Use Statistics in Germany (1883–2001) – HISTAT/GESIS",
      "url_or_doi": "https://histat.safe-frankfurt.de/index.php/en/project/details/9F49DE46FD3D98718A3673101AA2386E",
      "justification": "Highly relevant historical dataset containing land-use statistics for Germany, including the 1960s. Covers agricultural land, arable land, forests, and other land-use categories. Includes historical series for West Germany from 1938 to 1978 and agricultural land-use statistics from 1950 to 2001. Particularly useful for examining changes in land allocation, agricultural planning, and land-use patterns during the 1960s."
    },
    {
      "title": "LUCAS LUC Historical Land Use and Land Cover Change Dataset for Europe (1950–2015)",
      "url_or_doi": "https://doi.org/10.26050/WDCC/LUC_hist_landCovChange_v1.0",
      "justification": "Spatially explicit historical land-use and land-cover dataset covering Europe, including Germany, from 1950 to 2015. Provides annual reconstructed land-cover information, making it suitable for investigating land-use changes throughout the 1960s. Particularly valuable for GIS-based research on agricultural expansion, forest cover, and landscape transformations. The historical maps are reconstructions rather than direct observations from the 1960s."
    },
    {
      "title": "LUCAS LUC Historical Land Use and Land Cover Change Dataset for Europe, Version 1.1",
      "url_or_doi": "https://b2find.eudat.eu/dataset/bcfaa951-724f-55d0-8c92-0e883de4e487",
      "justification": "Historical geospatial dataset containing annual land-use and land-cover maps for Europe between 1950 and 2015. Includes Germany during the entire 1960s. Useful for analyzing historical land-cover patterns and comparing reconstructed land-use conditions across different years. Particularly relevant for environmental planning, agricultural geography, and long-term spatial development studies."
    },
    {
      "title": "Historical Statistics of Construction Activity and Housing in West Germany (1950–2005) – HISTAT",
      "url_or_doi": "https://histat.safe-frankfurt.de/index.php/en/project/details/B97512D84B3B3366BA7E521C19C429A0",
      "justification": "Historical statistical compilation documenting housing construction and building activity in Germany, including the 1960s. Contains information on completed residential buildings, housing construction, and residential floor space. Particularly useful for studying urban development, settlement expansion, residential planning, and construction patterns associated with West Germany's postwar economic growth. Provides planning-related indicators rather than direct land-use maps."
    },
    {
      "title": "Historical Housing Development Statistics in Germany (1918–1965) – HISTAT",
      "url_or_doi": "https://histat.safe-frankfurt.de/index.php/en/project/details/5218E3EFF9264CAC47629DC218DA0E48",
      "justification": "Historical dataset containing housing development indicators through 1965, including new housing construction, housing availability, and residential development. Relevant for examining urban planning and settlement growth during the first half of the 1960s. Useful for comparing housing development trends in East and West Germany and investigating the relationship between urbanization and land-use planning."
    },
    {
      "title": "Deutscher Planungsatlas: Niedersachsen und Bremen (1969) – GeoGREIF Historical Map Collection",
      "url_or_doi": "https://geogreif.uni-greifswald.de/search?init=D&map=theme&map_them=17",
      "justification": "Historical planning atlas material from 1969 covering Lower Saxony and Bremen. The GeoGREIF collection provides access to historical geographic and thematic maps, including regional planning atlas records. Particularly relevant for investigating spatial planning, regional development, settlement structures, and land-use organization in West Germany during the late 1960s. The link leads to a searchable collection rather than a single downloadable dataset."
    },
    {
      "title": "Basic Statistics of the European Economic Community (1965) – Agricultural Land Use",
      "url_or_doi": "https://aei.pitt.edu/52161/",
      "justification": "Historical statistical publication containing agricultural land-use data for West Germany in 1963. Includes measurements of arable land, permanent meadows and pastures, permanent crops, and total agricultural area. Provides quantitative evidence of land allocation during the early 1960s and enables comparisons between West Germany and other European countries. Useful for research on agricultural land management and rural planning."
    },
    {
      "title": "Long-term Development of Demand and Supply for Agricultural Products in the Federal Republic of Germany – USDA Economic Research Service",
      "url_or_doi": "https://ageconsearch.umn.edu/record/316836",
      "justification": "Historical agricultural study containing quantitative land-utilization data for West Germany during the 1960s. Includes agricultural land-use measurements for the 1961–1964 reference period and individual observations for 1964 and 1966, alongside projections for later years. Categories include cropland, permanent grassland, cereals, potatoes, sugar beets, and other crops. Particularly useful for studying agricultural planning, changes in cultivated land, and rural land-use allocation."
    },
    {
      "title": "Land Utilization in the European Economic Community (1966) – Historical Agricultural Statistics",
      "url_or_doi": "https://ageconsearch.umn.edu/record/272857",
      "justification": "Historical statistical source containing land-utilization figures for West Germany in 1966. Includes arable land, permanent meadows and pastures, permanent crops, total agricultural area, and forest area. Useful for analyzing the composition of agricultural and forest land in the mid-1960s and comparing German land-use patterns with those of other European Economic Community members."
    },
    {
      "title": "Historical Land Use and Land Cover Dynamics in Germany (1883–2007)",
      "url_or_doi": "https://pmc.ncbi.nlm.nih.gov/articles/PMC4375829/",
      "justification": "Research publication describing a historical land-use and land-cover data compilation covering Germany from 1883 to 2007. The underlying analysis uses official historical statistics at five-year intervals, including separate observations for East and West Germany between 1950 and 1989. Particularly relevant for studying agricultural land decline, forest recovery, and differences in land-use development under East and West German political and planning systems during the 1960s. This is a research article describing the assembled data rather than a dedicated dataset download page."
    }
  ]
}
